import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { LoginService } from './login.service';
import { MatSnackBar } from '@angular/material/snack-bar';


@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css'],
})
export class LoginComponent {
  passwordView: boolean = false;
  showPasswordRecoveryModal: boolean = false;
  form: FormGroup;
  errorMessage: string | null = null;

  constructor(
    private router: Router,
    private formBuilder: FormBuilder,
    private loginService: LoginService,
    private snackBar: MatSnackBar

  ) {
    this.form = formBuilder.group({
      login: ['', Validators.required],
      password: ['', Validators.required],
      rememberMe: [false],
    });
  }

  togglePasswordVisibility() {
    this.passwordView = !this.passwordView;
  }

  showPasswordRecovery() {
    this.showPasswordRecoveryModal = true;
  }

  closePasswordRecovery() {
    this.showPasswordRecoveryModal = false;
  }

  loginSystem() {
    if (this.form.valid) {
      const formValue = this.form.value;

      this.loginService
        .login(formValue.login, formValue.password)
        .subscribe({
          next: (response) => {
            this.loginService.setAuthToken(response.token);
            this.router.navigate(['/financi']);
          },
          error: (err) => {
            console.error('Erro no login:', err);

            if (err.status === 401) {
              this.showToast('Usuário ou senha inválidos!', 'error');
            } else {
              this.showToast('Erro ao realizar login. Tente novamente.', 'error');
            }
          },
        });
    } else {
      this.showToast('Por favor, preencha todos os campos.', 'warning');
    }
  }
  private showToast(message: string, type: 'error' | 'warning') {
    this.snackBar.open(message, 'Fechar', {
      duration: 3000,
      verticalPosition: 'top', 
      horizontalPosition: 'center', 
      panelClass: type === 'error' ? ['snackbar-error'] : ['snackbar-warning'],
    });
  }

}

<div class="login-container">
  <div class="left-section">
    <form class="align-form" [formGroup]="form">
      <div class="svg-logo">
        <img
          src="assets/imagem/Internapp-icon.svg"
          class="logo-image"
          width="223.17px"
          height="39.67px"
        />
      </div>
      <label class="description" for="email">Endereço de e-mail</label>
      <input
        type="text"
        id="email"
        placeholder="example@gmail.com"
        formControlName="login"
      />
      <label class="description" for="senha">Senha</label>
      <input
        [type]="passwordView ? 'text' : 'password'"
        placeholder="Senha"
        formControlName="password"
      />
      <div class="checkbox-forgot">
        <label class="remember-me">
          <input class="check" type="checkbox" formControlName="rememberMe" />
          Lembrar-me
        </label>
        <a
          class="forgot-password"
          (click)="showPasswordRecovery()"
          href="#"
        >
          Esqueceu sua senha?
        </a>
      </div>
      <div *ngIf="errorMessage" class="error-message">
        {{ errorMessage }}
      </div>
      <div class="button">
        <button type="button" (click)="loginSystem()">Entrar</button>
      </div>
    </form>
  </div>
  <div class="right-section">
    <img
      src="assets/imagem/logo.svg"
      class="background-image"
      width="647"
      height="602"
    />
  </div>
</div>
<app-recover-password
  *ngIf="showPasswordRecoveryModal"
  (closeModal)="closePasswordRecovery()"
></app-recover-password>
